CREATE TABLE "tblConfirmation"
(
    "Id"            BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "DisputeId"     BIGINT                                  NOT NULL,
    "OutboxEventId" UUID                                    NOT NULL,
    "Message"       VARCHAR(200)                            NOT NULL,
    "CreatedAt"     TIMESTAMP WITH TIME ZONE                NOT NULL,

    CONSTRAINT "PK_Confirmation" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_Confirmation_OutboxEventId" UNIQUE ("OutboxEventId"),
    CONSTRAINT "FK_Confirmation_Dispute" FOREIGN KEY ("DisputeId") REFERENCES "tblDispute" ("Id")
);

CREATE INDEX "IX_Confirmation_DisputeId" ON "tblConfirmation" ("DisputeId");
